package reader

import (
	"encoding/csv"
	"errors"
	"io"
)

// Table is a parsed CSV file: the first record is the header and every later record is a row.
type Table struct {
	Header []string   // first record
	Rows   [][]string // later records, in file order
	Lines  []int      // 1-based input line on which each row starts; len(Lines) == len(Rows)
}

// Read parses r with encoding/csv. Field counts are not checked here; see Validate.
// An empty input returns a zero Table and a nil error.
func Read(r io.Reader) (Table, error) {
	cr := csv.NewReader(r)
	cr.FieldsPerRecord = -1

	var t Table
	for {
		rec, err := cr.Read()
		if errors.Is(err, io.EOF) {
			return t, nil
		}
		if err != nil {
			return Table{}, err
		}
		if t.Header == nil {
			t.Header = rec
			continue
		}
		line, _ := cr.FieldPos(0)
		t.Rows = append(t.Rows, rec)
		t.Lines = append(t.Lines, line)
	}
}
EOF
cat > internal/reader/trim.go <<'EOF'
package reader

import "strings"

// Trim removes leading and trailing space characters (U+0020) only.
func Trim(s string) string {
	return strings.Trim(s, " ")
}

// IsNull reports whether an already trimmed value is null: empty, or NA, N/A, or NULL
// ignoring case. Every other value is non-null.
func IsNull(s string) bool {
	return s == "" ||
		strings.EqualFold(s, "NA") ||
		strings.EqualFold(s, "N/A") ||
		strings.EqualFold(s, "NULL")
}

// TrimTable returns a copy of t with every header name and every value trimmed. Lines is kept.
func TrimTable(t Table) Table {
	out := Table{
		Header: trimAll(t.Header),
		Rows:   make([][]string, len(t.Rows)),
		Lines:  append([]int(nil), t.Lines...),
	}
	for i, row := range t.Rows {
		out.Rows[i] = trimAll(row)
	}
	return out
}

func trimAll(values []string) []string {
	out := make([]string, len(values))
	for i, v := range values {
		out[i] = Trim(v)
	}
	return out
}
EOF
cat > internal/reader/validate.go <<'EOF'
package reader

import "fmt"

// RejectError reports input that was read but rejected. It is a content failure and exits 3.
type RejectError struct {
	Line   int // 1-based input line of the offending record; 0 when the whole file is rejected
	Reason string
}

func (e *RejectError) Error() string {
	if e.Line == 0 {
		return e.Reason
	}
	return fmt.Sprintf("line %d: %s", e.Line, e.Reason)
}

// Validate checks a trimmed table. It rejects an empty file, an empty or repeated header name,
// and any record whose field count differs from the header. A header-only table is valid.
func Validate(t Table) error {
	if len(t.Header) == 0 {
		return &RejectError{Reason: "file is empty"}
	}
	seen := make(map[string]bool, len(t.Header))
	for i, name := range t.Header {
		if name == "" {
			return &RejectError{Reason: fmt.Sprintf("header name %d is empty", i+1)}
		}
		if seen[name] {
			return &RejectError{Reason: fmt.Sprintf("header name %q is repeated", name)}
		}
		seen[name] = true
	}
	for i, row := range t.Rows {
		if len(row) != len(t.Header) {
			return &RejectError{
				Line:   t.Lines[i],
				Reason: fmt.Sprintf("record has %d fields, header has %d", len(row), len(t.Header)),
			}
		}
	}
	return nil
}
EOF
cat > internal/typing/typing.go <<'EOF'
package typing

import (
	"regexp"
	"strings"
	"time"

	"csvstat/internal/reader"
)

var (
	integerPattern = regexp.MustCompile(`^-?[0-9]+$`)
	numberPattern  = regexp.MustCompile(`^-?[0-9]+(\.[0-9]+)?$`)
	datePattern    = regexp.MustCompile(`^[0-9]{4}-[0-9]{2}-[0-9]{2}$`)
)

// Infer returns the type token of a column from its trimmed values. Null values are skipped.
// The first of integer, number, date, boolean, text that every non-null value satisfies wins;
// a column with no non-null value is empty.
func Infer(values []string) string {
	found := false
	isInt, isNum, isDate, isBool := true, true, true, true
	for _, v := range values {
		if reader.IsNull(v) {
			continue
		}
		found = true
		isInt = isInt && integerPattern.MatchString(v)
		isNum = isNum && numberPattern.MatchString(v)
		isDate = isDate && IsDate(v)
		isBool = isBool && (strings.EqualFold(v, "true") || strings.EqualFold(v, "false"))
	}
	switch {
	case !found:
		return "empty"
	case isInt:
		return "integer"
	case isNum:
		return "number"
	case isDate:
		return "date"
	case isBool:
		return "boolean"
	default:
		return "text"
	}
}

// IsDate reports whether s is a real calendar date written YYYY-MM-DD. Leap years are honored
// and no value is normalized into validity.
func IsDate(s string) bool {
	if !datePattern.MatchString(s) {
		return false
	}
	t, err := time.Parse("2006-01-02", s)
	return err == nil && t.Format("2006-01-02") == s
}
EOF
cat > internal/profile/profile.go <<'EOF'
package profile

import (
	"fmt"
	"math/big"
	"sort"
	"strings"

	"csvstat/internal/reader"
	"csvstat/internal/typing"
)

// Column is one row of the profile. Statistic fields are empty when they do not apply.
type Column struct {
	Name     string
	Type     string
	Rows     int
	Nulls    int
	Distinct int
	Min      string
	Max      string
	Sum      string
	Mean     string
	Median   string
}

// Describe profiles one column from its trimmed values.
func Describe(name string, values []string) Column {
	rows, nulls, distinct := Counts(values)
	typ := typing.Infer(values)
	lo, hi := MinMax(typ, values)
	sum, mean, median := NumericStats(typ, values)
	return Column{
		Name: name, Type: typ,
		Rows: rows, Nulls: nulls, Distinct: distinct,
		Min: lo, Max: hi, Sum: sum, Mean: mean, Median: median,
	}
}

// Counts returns the number of data values, the number of null values, and the number of
// distinct non-null values. The values must already be trimmed; comparison is exact.
func Counts(values []string) (rows, nulls, distinct int) {
	seen := make(map[string]struct{})
	for _, v := range values {
		if reader.IsNull(v) {
			nulls++
			continue
		}
		seen[v] = struct{}{}
	}
	return len(values), nulls, len(seen)
}

// MinMax returns the smallest and largest non-null value for a column of type typ.
// Integers and numbers compare exactly; numbers are written with two decimal places.
// Booleans report false/true in lowercase. Text and dates compare by byte value.
func MinMax(typ string, values []string) (lo, hi string) {
	nonNull := nonNullValues(values)
	if len(nonNull) == 0 {
		return "", ""
	}
	switch typ {
	case "integer", "number":
		low, high := ratOf(nonNull[0]), ratOf(nonNull[0])
		for _, v := range nonNull[1:] {
			r := ratOf(v)
			if r.Cmp(low) < 0 {
				low = r
			}
			if r.Cmp(high) > 0 {
				high = r
			}
		}
		if typ == "integer" {
			return low.Num().String(), high.Num().String()
		}
		return fixed2(low), fixed2(high)
	case "date", "text":
		lo, hi = nonNull[0], nonNull[0]
		for _, v := range nonNull[1:] {
			if v < lo {
				lo = v
			}
			if v > hi {
				hi = v
			}
		}
		return lo, hi
	case "boolean":
		lo, hi = "true", "false"
		for _, v := range nonNull {
			if strings.EqualFold(v, "false") {
				lo = "false"
			}
			if strings.EqualFold(v, "true") {
				hi = "true"
			}
		}
		return lo, hi
	default:
		return "", ""
	}
}

// NumericStats returns the sum, mean, and median of an integer or number column. Every other
// type returns three empty strings. Arithmetic is exact; rounding happens once when writing.
func NumericStats(typ string, values []string) (sum, mean, median string) {
	if typ != "integer" && typ != "number" {
		return "", "", ""
	}
	nonNull := nonNullValues(values)
	if len(nonNull) == 0 {
		return "", "", ""
	}
	nums := make([]*big.Rat, len(nonNull))
	total := new(big.Rat)
	for i, v := range nonNull {
		nums[i] = ratOf(v)
		total.Add(total, nums[i])
	}
	sort.Slice(nums, func(i, j int) bool { return nums[i].Cmp(nums[j]) < 0 })

	n := len(nums)
	var mid *big.Rat
	if n%2 == 1 {
		mid = nums[n/2]
	} else {
		mid = new(big.Rat).Add(nums[n/2-1], nums[n/2])
		mid.Quo(mid, big.NewRat(2, 1))
	}
	avg := new(big.Rat).Quo(total, big.NewRat(int64(n), 1))

	if typ == "integer" {
		sum = total.Num().String()
	} else {
		sum = fixed2(total)
	}
	return sum, fixed2(avg), fixed2(mid)
}

func nonNullValues(values []string) []string {
	out := make([]string, 0, len(values))
	for _, v := range values {
		if !reader.IsNull(v) {
			out = append(out, v)
		}
	}
	return out
}

// ratOf parses a value already accepted by the integer or number pattern. Those patterns are
// a subset of big.Rat syntax, so the parse cannot fail for a value that reached here.
func ratOf(s string) *big.Rat {
	r, _ := new(big.Rat).SetString(s)
	return r
}

// fixed2 writes x with exactly two decimal places, rounding once, half away from zero.
// A negative result that rounds to zero is written without a sign.
func fixed2(x *big.Rat) string {
	a := new(big.Rat).Abs(x)
	// floor(a*100 + 1/2) = floor((200*num + den) / (2*den)) for a non-negative a.
	num := new(big.Int).Mul(a.Num(), big.NewInt(200))
	num.Add(num, a.Denom())
	q := new(big.Int).Quo(num, new(big.Int).Mul(a.Denom(), big.NewInt(2)))

	whole, frac := new(big.Int).QuoRem(q, big.NewInt(100), new(big.Int))
	s := fmt.Sprintf("%s.%02d", whole.String(), frac.Int64())
	if x.Sign() < 0 && q.Sign() != 0 {
		s = "-" + s
	}
	return s
}
EOF
cat > internal/freq/freq.go <<'EOF'
package freq

import (
	"sort"

	"csvstat/internal/reader"
)

// Entry is one distinct non-null value and how many times it occurs.
type Entry struct {
	Value string
	Count int
}

// Top returns at most n of the most frequent non-null values. Values are trimmed before
// counting. Entries are ordered by count descending, then value ascending by byte value.
func Top(values []string, n int) []Entry {
	counts := make(map[string]int)
	for _, raw := range values {
		v := reader.Trim(raw)
		if reader.IsNull(v) {
			continue
		}
		counts[v]++
	}
	entries := make([]Entry, 0, len(counts))
	for v, c := range counts {
		entries = append(entries, Entry{Value: v, Count: c})
	}
	sort.Slice(entries, func(i, j int) bool {
		if entries[i].Count != entries[j].Count {
			return entries[i].Count > entries[j].Count
		}
		return entries[i].Value < entries[j].Value
	})
	if n < 0 {
		n = 0
	}
	if n < len(entries) {
		entries = entries[:n]
	}
	return entries
}
EOF
cat > internal/output/output.go <<'EOF'
package output

import (
	"encoding/csv"
	"io"
	"strconv"

	"csvstat/internal/freq"
	"csvstat/internal/profile"
)

var (
	profileHeader = []string{"column", "type", "rows", "nulls", "distinct", "min", "max", "sum", "mean", "median"}
	freqHeader    = []string{"value", "count"}
)

// WriteProfile writes the profile header and one row per column as RFC 4180 CSV with LF endings.
func WriteProfile(w io.Writer, cols []profile.Column) error {
	cw := csv.NewWriter(w)
	if err := cw.Write(profileHeader); err != nil {
		return err
	}
	for _, c := range cols {
		rec := []string{
			c.Name, c.Type,
			strconv.Itoa(c.Rows), strconv.Itoa(c.Nulls), strconv.Itoa(c.Distinct),
			c.Min, c.Max, c.Sum, c.Mean, c.Median,
		}
		if err := cw.Write(rec); err != nil {
			return err
		}
	}
	cw.Flush()
	return cw.Error()
}

// WriteFreq writes the frequency header and one row per entry as RFC 4180 CSV with LF endings.
func WriteFreq(w io.Writer, entries []freq.Entry) error {
	cw := csv.NewWriter(w)
	if err := cw.Write(freqHeader); err != nil {
		return err
	}
	for _, e := range entries {
		if err := cw.Write([]string{e.Value, strconv.Itoa(e.Count)}); err != nil {
			return err
		}
	}
	cw.Flush()
	return cw.Error()
}
EOF
